def rand_graph(rng, nv_max=_sage_const_3 , emax=_sage_const_7 , box=_sage_const_3 ):
    m = rng.randint(_sage_const_1 , nv_max)
    r = rng.randint(_sage_const_2 , emax)
    edges = []
    for _ in range(r):
        if m == _sage_const_1 :
            u = v = _sage_const_0 
        else:
            u = rng.randrange(m); v = rng.randrange(m)
        edges.append((u, v, (rng.randint(-box, box), rng.randint(-box, box))))
    return m, edges

SAMPLES = int(_sage_const_3000 )
