    rng = random.Random(int(_sage_const_20260731 ) + int(ell))
    t0 = time.time()
    st = Counter()
    joint = Counter()
    for _ in range(SAMPLES):
        m, edges = rand_graph(rng)
        inv = invariants(m, edges, ell)
        if inv is None:
            continue
        st['有効'] += _sage_const_1 
        st['k=%d' % inv['k']] += _sage_const_1 
        if len(inv['zeros']) != _sage_const_0 :
            st['退化'] += _sage_const_1 
            continue
        st['非退化'] += _sage_const_1 
